(async () => {
  const post=(u,b,t)=>fetch(u,{method:'POST',headers:Object.assign({'Content-Type':'application/json'},t?{'X-User-Token':t}:{}),body:JSON.stringify(b||{})}).then(r=>r.json());
  const un='bk_'+Math.floor(Math.random()*1e7);
  await post('/api/users/register',{username:un,password:'test1234',nickname:'技能书面板测试'});
  const lg=await post('/api/users/login',{username:un,password:'test1234'});
  Auth.setSession(lg.token,lg.user);
  await post('/api/users/me/library/1',{},lg.token);
  const uc=await post('/api/users/me/characters',{game_id:1,base_character_id:1},lg.token);
  if(!uc||!uc.id) return 'create-failed:'+JSON.stringify(uc).slice(0,150);
  const full=await fetch('/api/users/me/characters/'+uc.id+'/full',{headers:{'X-User-Token':lg.token}}).then(r=>r.json());
  const base=(full&&full.base_character)||{};
  window.__UC=uc; window.__FULL=full;
  App._currentUC=uc; GameState.userCharacter=uc;
  GameState.player=Object.assign({},GameState.player||{},{
    id:uc.id, uc_id:uc.id, base_id:uc.base_character_id,
    name:uc.custom_name||base.name||'玩家',
    level:uc.level, realm_level:uc.realm_level, exp:uc.exp,
    hp:uc.hp, max_hp:uc.max_hp, mp:uc.mp, max_mp:uc.max_mp,
    attack:uc.attack, defense:uc.defense, speed:uc.speed, luck:uc.luck,
    portrait_image:base.portrait_image||'',
  });
  GameState.updatePlayerUI();
  const gc=document.querySelector('#game-container'); if(gc) gc.style.display='block';
  const pf=document.querySelector('#platform-layer'); if(pf) pf.classList.add('hidden');
  await CharacterPanel.show();
  await new Promise(r=>setTimeout(r,1200));
  const words=(document.querySelector('.cp2-word-list')||{innerText:''}).innerText||'';
  const slots=[...document.querySelectorAll('.cp2-slot[data-slot=\'skill\']')].map(s=>(s.querySelector('.cp2-slot-label')||{}).textContent||'');
  return JSON.stringify({ucId:uc.id, name:GameState.player.name, books:words.replace(/\s+/g,' ').slice(0,300), skillSlots:slots});
})()
